css:
.boreal-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2530;
    background: linear-gradient(165deg, #eceff1 0%, #e3e8eb 55%, #dde4e3 100%);
    border-radius: 16px;
}

.boreal-container * {
    box-sizing: border-box;
}

.boreal-header {
    text-align: center;
    padding: 30px 24px 26px;
    background: linear-gradient(135deg, #1f2a33 0%, #2f4858 52%, #11705a 100%);
    color: #f1f5f4;
    border-radius: 14px;
    margin-bottom: 18px;
    box-shadow: 0 16px 36px rgba(31, 42, 51, 0.34);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.boreal-header h1 {
    margin: 12px 0 12px;
    font-size: 2.45rem;
    font-weight: 800;
    letter-spacing: -0.6px;
    color: #ffffff;
}

.boreal-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #8fe3c8;
    background: rgba(143, 227, 200, 0.12);
    border: 1px solid rgba(143, 227, 200, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.boreal-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd9d6;
}

.boreal-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.boreal-firm {
    flex: 1;
    background: #ffffff;
    border-radius: 12px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(28, 37, 48, 0.09);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.boreal-firm-asset { border-left: 5px solid #b3541e; }
.boreal-firm-cost { border-left: 5px solid #c0392b; }

.boreal-firm-name {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f2a33;
    font-variant-numeric: tabular-nums;
}

.boreal-firm-asset .boreal-firm-name { color: #b3541e; }
.boreal-firm-cost .boreal-firm-name { color: #c0392b; }

.boreal-firm-meta {
    font-size: 0.82rem;
    color: #5a6b75;
    line-height: 1.4;
}

.boreal-firm-plus {
    align-self: center;
    font-size: 1.7rem;
    font-weight: 800;
    color: #2f4858;
}

.boreal-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44535f;
    margin-bottom: 16px;
    padding: 4px;
}

.boreal-period-counter #currentDay,
.boreal-period-counter #maxPeriods {
    font-weight: 800;
    color: #11705a;
}

.boreal-round-name {
    background: rgba(17, 112, 90, 0.13);
    color: #0d5e4b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.boreal-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b3541e;
    background: rgba(179, 84, 30, 0.13);
    border: 1px solid rgba(179, 84, 30, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.boreal-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.boreal-status-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.09);
    border-top: 4px solid #2f4858;
}

.boreal-card-abate { border-top-color: #11705a; }
.boreal-card-coalition { border-top-color: #2f6fb0; }
.boreal-card-share { border-top-color: #b3541e; }
.boreal-card-cred { border-top-color: #7d5fc0; }

.boreal-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #67767f;
}

.boreal-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a33;
    font-variant-numeric: tabular-nums;
}

.boreal-card-abate .boreal-value { color: #11705a; }
.boreal-card-coalition .boreal-value { color: #2f6fb0; }
.boreal-card-share .boreal-value { color: #b3541e; }
.boreal-card-cred .boreal-value { color: #7d5fc0; }

.boreal-sublabel {
    font-size: 0.76rem;
    color: #76858d;
    line-height: 1.35;
}

.boreal-card-share.boreal-share-up { border-top-color: #11705a; }
.boreal-card-share.boreal-share-up .boreal-value { color: #11705a; }
.boreal-card-share.boreal-share-down { border-top-color: #c0392b; }
.boreal-card-share.boreal-share-down .boreal-value { color: #c0392b; }

.boreal-card-coalition.boreal-coalition-low { border-top-color: #c0392b; }
.boreal-card-coalition.boreal-coalition-low .boreal-value { color: #c0392b; }

.boreal-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d7dee1;
    color: #44535f;
    padding: 10px 18px;
    border-radius: 11px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.boreal-threat-bar #threatDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
}

.boreal-threat-bar.boreal-threat-low #threatDisplay { color: #11705a; }
.boreal-threat-bar.boreal-threat-mid #threatDisplay { color: #b3541e; }

.boreal-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #11705a;
    border-radius: 11px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.08);
}

.boreal-briefing-icon {
    font-size: 1.85rem;
    line-height: 1;
}

.boreal-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f2a33;
    margin-bottom: 6px;
}

.boreal-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4954;
}

.boreal-briefing-text strong { color: #11705a; }
.boreal-briefing-text em { color: #b3541e; font-style: italic; }

.boreal-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.08);
}

.boreal-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f2a33;
    border-bottom: 2px solid #e4e9eb;
    padding-bottom: 8px;
}

.boreal-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28333d;
    margin: 14px 0 6px;
}

.boreal-container select,
.boreal-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3ccd1;
    border-radius: 8px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2530;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.boreal-container select:focus,
.boreal-container input[type="number"]:focus {
    outline: none;
    border-color: #11705a;
    box-shadow: 0 0 0 3px rgba(17, 112, 90, 0.16);
}

.boreal-container select option {
    background-color: #ffffff;
    color: #1c2530;
}

.boreal-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #11705a;
}

.boreal-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44535f;
    margin-top: 4px;
}

.boreal-range-readout span:nth-child(2) {
    color: #11705a;
    font-weight: 800;
}

.boreal-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 8px 0 4px;
}

.boreal-alloc-row {
    display: flex;
    align-items: center;
    gap: 10px;
    background: #f6f8f8;
    border: 1px solid #e1e7e8;
    border-radius: 9px;
    padding: 8px 12px;
}

.boreal-alloc-name {
    flex: 1;
    font-size: 0.9rem;
    font-weight: 700;
    color: #28333d;
}

.boreal-alloc-row input[type="number"] {
    width: 110px;
    flex: 0 0 auto;
}

.boreal-alloc-unit {
    font-size: 0.8rem;
    font-weight: 700;
    color: #67767f;
    flex: 0 0 auto;
}

.boreal-macc {
    display: inline-block;
    margin-left: 4px;
    font-size: 0.72rem;
    font-weight: 700;
    padding: 1px 8px;
    border-radius: 999px;
    vertical-align: middle;
}

.boreal-macc-good { color: #0d5e4b; background: rgba(17, 112, 90, 0.14); }
.boreal-macc-mid { color: #b3541e; background: rgba(179, 84, 30, 0.14); }
.boreal-macc-bad { color: #c0392b; background: rgba(192, 57, 43, 0.13); }

.boreal-alloc-total {
    font-size: 0.92rem;
    font-weight: 800;
    color: #2f4858;
    margin-top: 8px;
    font-variant-numeric: tabular-nums;
}

.boreal-alloc-total #allocTotal { color: #11705a; }
.boreal-alloc-total.boreal-alloc-over #allocTotal { color: #c0392b; }

.boreal-hint {
    font-size: 0.8rem;
    color: #76858d;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.boreal-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.boreal-container .btn-primary {
    background: linear-gradient(135deg, #2f4858 0%, #11705a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 8px;
    box-shadow: 0 8px 18px rgba(17, 112, 90, 0.30);
}

.boreal-container .btn-primary:hover {
    filter: brightness(1.08);
}

.boreal-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c3ccd1;
    color: #5a6b75;
    background: transparent;
}

.boreal-coach {
    background: linear-gradient(160deg, #1f2a33 0%, #2a3a44 100%);
    color: #dde9e5;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(31, 42, 51, 0.26);
}

.boreal-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fe3c8;
    margin-bottom: 8px;
}

.boreal-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.boreal-coach-body strong { color: #7fe0cf; }
.boreal-coach-body em { color: #f0b27a; font-style: italic; }

.boreal-history,
.boreal-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 37, 48, 0.08);
}

.boreal-history h3,
.boreal-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f2a33;
}

.boreal-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4954;
}

.boreal-container table#usfHistoryTable th {
    background: #eaf0ef;
    color: #0d5e4b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d5e0dc;
}

.boreal-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f1;
    color: #3a4954;
}

.boreal-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6f9f8;
}

.boreal-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .boreal-container {
        padding: 14px;
    }
    .boreal-header h1 {
        font-size: 1.7rem;
    }
    .boreal-firms {
        flex-direction: column;
    }
    .boreal-firm-plus {
        transform: rotate(90deg);
    }
    .boreal-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .boreal-value {
        font-size: 2rem;
    }
    .boreal-clock {
        margin-left: 0;
    }
    .boreal-period-counter {
        font-size: 0.88rem;
    }
    .boreal-threat-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .boreal-alloc-row {
        flex-wrap: wrap;
    }
    .boreal-alloc-row input[type="number"] {
        width: 90px;
    }
    .boreal-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-transition debrief scorecard (append-only, namespaced) ===== */
.lt-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.lt-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.lt-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.lt-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.lt-cm-score strong { color: #4f9bd9; }
.lt-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.lt-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.lt-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.lt-cm-target.lt-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.lt-cm-target.lt-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.lt-cm-tick { font-weight: 700; }
.lt-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.lt-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.lt-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.lt-cm-metric strong { font-size: 16px; color: #eceff6; }
.lt-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.lt-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .lt-cm-metric { min-width: 70px; } .lt-cm-verdict { font-size: 19px; } }

