(function() {
    'use strict';

    class LeadTransitionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Lead the Transition`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Boréal Matériaux inc.).
            this.BUDGET = 600;            // CA$600M transition capex over 5 years
            this.EMISSIONS = 2.6;         // Mt CO₂ / year
            this.CARBON_2030 = 170;       // CA$/tonne by 2030
            this.ACTIVIST = 4.8;          // % activist stake
            this.AT_RISK_JOBS = 480;      // jobs at the oldest kiln
            this.START_SHARE = 100;       // indexed share price (day 1)
            this.START_COALITION = 50;    // coalition support 0–100
            this.START_CRED = 5.0;        // plan credibility /10

            // Concept truths (the modelled path).
            this.TRUE_DIAG = `process`;
            this.TRUE_POLAR = `multi`;
            this.TRUE_POSTURE = `sequence`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    abate: 0,                         // % of 2.6 Mt on a credible path to abatement
                    coalition: this.START_COALITION,  // coalition support 0–100
                    share: this.START_SHARE,          // indexed share price (100 = day 1)
                    cred: this.START_CRED,            // plan credibility /10
                    proxyRisk: 70,                    // proxy-fight risk 0–100 (lower safer)
                    polarizedRun: false,              // pleased one pole, mobilized the other
                    idledKiln: false,                 // idled the kiln (just-transition failure)
                    symbolicBudget: false,            // over-funded capture for optics
                    overPromised: false,              // committed un-deliverable targets
                    dividendSilent: false,            // never addressed the dividend
                    captureSpend: 0,                  // CA$M put into the capture pilot
                    abateHistory: [0],
                    coalitionHistory: [this.START_COALITION],
                    shareHistory: [this.START_SHARE],
                    credHistory: [this.START_CRED],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    diag: `all`,
                    polar: `activist`,
                    posture: `rush`,
                    listen: 30,
                    fuels: 60,
                    clinker: 60,
                    electric: 60,
                    capture: 60,
                    pace: 70,
                    union: `idle`,
                    investor: `esg`,
                    gov: `dismiss`,
                    dividend: `cut`,
                    target: `overpromise`,
                    metrics: `hide`,
                    proxy: `capitulate`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const po = document.getElementById(`polarInput`);
                const ps = document.getElementById(`postureInput`);
                const li = document.getElementById(`listenInput`);
                if (dg) decisions.diag = dg.value;
                if (po) decisions.polar = po.value;
                if (ps) decisions.posture = ps.value;
                if (li) decisions.listen = parseInt(li.value, 10);
                if (!Number.isFinite(decisions.listen) || decisions.listen < 0 || decisions.listen > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 2) {
                const fu = document.getElementById(`fuelsInput`);
                const cl = document.getElementById(`clinkerInput`);
                const el = document.getElementById(`electricInput`);
                const ca = document.getElementById(`captureInput`);
                const pa = document.getElementById(`paceInput`);
                if (fu) decisions.fuels = parseFloat(fu.value);
                if (cl) decisions.clinker = parseFloat(cl.value);
                if (el) decisions.electric = parseFloat(el.value);
                if (ca) decisions.capture = parseFloat(ca.value);
                if (pa) decisions.pace = parseInt(pa.value, 10);
                const vals = [decisions.fuels, decisions.clinker, decisions.electric, decisions.capture];
                if (vals.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_value`); return false;
                }
                const total = vals.reduce((a, b) => a + b, 0);
                if (total > this.BUDGET) {
                    warn(`warn_alloc_over`); return false;
                }
                if (!Number.isFinite(decisions.pace) || decisions.pace < 0 || decisions.pace > 100) {
                    warn(`warn_pace_range`); return false;
                }
            } else if (round === 3) {
                const un = document.getElementById(`unionInput`);
                const iv = document.getElementById(`investorInput`);
                const gv = document.getElementById(`govInput`);
                const dv = document.getElementById(`dividendInput`);
                if (un) decisions.union = un.value;
                if (iv) decisions.investor = iv.value;
                if (gv) decisions.gov = gv.value;
                if (dv) decisions.dividend = dv.value;
            } else if (round === 4) {
                const tg = document.getElementById(`targetInput`);
                const mt = document.getElementById(`metricsInput`);
                const px = document.getElementById(`proxyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (tg) decisions.target = tg.value;
                if (mt) decisions.metrics = mt.value;
                if (px) decisions.proxy = px.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let abateDelta = 0, coalitionDelta = 0, shareDelta = 0, credDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the transition & the polarization (Common Error: mis-diagnosis).
                switch (d.diag) {
                    case `process`: credDelta += 1.0; riskDelta -= 6; coachKey = `coach_r1_process`; break;
                    case `electricity`: credDelta -= 0.6; riskDelta += 5; coachKey = `coach_r1_electricity`; break;
                    case `all`: credDelta -= 0.9; riskDelta += 7; coachKey = `coach_r1_all`; break;
                }

                switch (d.polar) {
                    case `multi`: coalitionDelta += 4; riskDelta -= 6; break;
                    case `activist`: coalitionDelta -= 4; riskDelta += 5; ds.polarizedRun = true; coachKey = `coach_r1_activist`; break;
                    case `ignore`: coalitionDelta -= 5; riskDelta += 7; coachKey = `coach_r1_ignore`; break;
                }

                switch (d.posture) {
                    case `sequence`: credDelta += 0.9; coalitionDelta += 4; riskDelta -= 7; if (d.diag === `process` && d.polar === `multi`) coachKey = `coach_r1_sharp`; break;
                    case `rush`: shareDelta -= 5; credDelta -= 0.8; riskDelta += 8; ds.polarizedRun = true; coachKey = `coach_r1_rush`; break;
                    case `stall`: coalitionDelta -= 3; credDelta -= 0.6; riskDelta += 6; coachKey = `coach_r1_stall`; break;
                }

                // Consultation = a coalition lever from the start.
                if (d.listen >= 60) { coalitionDelta += 5; riskDelta -= 5; }
                else if (d.listen <= 20) { coalitionDelta -= 3; riskDelta += 4; }

                summaryKey = (d.diag === `process` && d.polar === `multi` && d.posture === `sequence`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sequence the initiatives & allocate the CA$600M budget (Common Error: symbolic budgeting).
                const fuels = d.fuels, clinker = d.clinker, electric = d.electric, capture = d.capture;
                const total = fuels + clinker + electric + capture;
                ds.captureSpend = capture;

                // Abatement effect is COST-WEIGHTED: cheap, ready levers buy far more tonnes per CA$M.
                // Approx tonnes/CA$M ~ inverse of CA$/t; readiness multiplies near-term realization.
                const tonnes =
                    fuels * 1.00 +       // ~CA$40/t, ready
                    clinker * 0.78 +     // ~CA$55/t, ready/scalable
                    electric * 0.42 +    // ~CA$110/t, partial/multi-year
                    capture * 0.18;      // CA$200+/t, pilot/unproven
                // Normalize to a % of the 2.6 Mt on a credible path; full smart spend ~ up to ~52%.
                abateDelta += Math.min(40, tonnes / 14.5);

                // Symbolic budgeting: over-funding the capture pilot for optics.
                if (capture >= 200) {
                    ds.symbolicBudget = true;
                    credDelta -= 1.2; shareDelta -= 3; riskDelta += 5; coachKey = `coach_r2_capture`;
                } else if (capture >= 100 && capture > fuels && capture > clinker) {
                    ds.symbolicBudget = true;
                    credDelta -= 0.6; riskDelta += 3; coachKey = `coach_r2_capture`;
                }

                // MACC discipline rewarded: cheap-and-ready levers carry the load, capture stays a small pilot.
                const cheapShare = total > 0 ? (fuels + clinker) / total : 0;
                if (cheapShare >= 0.55 && capture <= 90 && total >= 400) {
                    credDelta += 1.1; coalitionDelta += 3; riskDelta -= 5;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_macc`;
                } else if (Math.abs(fuels - capture) <= 20 && Math.abs(fuels - electric) <= 20 && Math.abs(fuels - clinker) <= 20) {
                    // An even split across all four levers (decision tree #3).
                    credDelta -= 0.7; riskDelta += 3; coachKey = `coach_r2_even`;
                }

                // Under-spending the budget leaves abatement and credibility on the table.
                if (total < 350) { credDelta -= 0.7; abateDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_under`; }

                // Front-loading: capex now hits EPS and the dividend — the share-price reacts.
                const pace = d.pace / 100;
                shareDelta -= Math.round((total / this.BUDGET) * pace * 10);   // front-loaded capex pressures the stock now
                if (pace <= 0.35) { abateDelta -= 3; } // too slow defers the abatement / lets the carbon bill compound

                summaryKey = (cheapShare >= 0.55 && capture <= 90 && total >= 400) ? `sum_r2_good` :
                             (ds.symbolicBudget ? `sum_r2_symbolic` :
                             (total < 350 ? `sum_r2_under` : `sum_r2_weak`));
            } else if (round === 3) {
                // Hold the coalition together (Common Errors 2 & 5).
                // The kiln & the just transition.
                switch (d.union) {
                    case `just`: coalitionDelta += 7; credDelta += 0.6; riskDelta -= 7; abateDelta += 3; break;
                    case `idle`: ds.idledKiln = true; abateDelta += 8; coalitionDelta -= 14; shareDelta -= 4; riskDelta += 12; coachKey = `coach_r3_idle`; break;
                    case `ignore`: coalitionDelta -= 5; credDelta -= 0.5; riskDelta += 5; coachKey = `coach_r3_unionignore`; break;
                }

                // Investor positioning.
                switch (d.investor) {
                    case `bridge`: coalitionDelta += 6; credDelta += 0.7; shareDelta += 4; riskDelta -= 6; break;
                    case `esg`: ds.polarizedRun = true; coalitionDelta -= 6; shareDelta -= 7; riskDelta += 8; coachKey = `coach_r3_esg`; break;
                    case `value`: credDelta -= 0.6; abateDelta -= 3; coalitionDelta -= 3; coachKey = `coach_r3_value`; break;
                }

                // Province & NGOs.
                switch (d.gov) {
                    case `compact`: coalitionDelta += 6; credDelta += 0.6; abateDelta += 2; riskDelta -= 6; break;
                    case `gov_only`: coalitionDelta += 1; riskDelta += 3; coachKey = `coach_r3_govonly`; break;
                    case `dismiss`: coalitionDelta -= 6; credDelta -= 0.5; riskDelta += 7; shareDelta -= 3; coachKey = `coach_r3_dismiss`; break;
                }

                // The dividend question (decision tree #5).
                switch (d.dividend) {
                    case `hold`: shareDelta += 6; coalitionDelta += 4; riskDelta -= 5; break;
                    case `cut`: shareDelta -= 9; coalitionDelta -= 4; riskDelta += 6; coachKey = `coach_r3_divcut`; break;
                    case `silent`: ds.dividendSilent = true; shareDelta -= 7; riskDelta += 5; coachKey = `coach_r3_divsilent`; break;
                }

                summaryKey = (d.union === `just` && d.investor === `bridge` && d.gov === `compact` && d.dividend === `hold`) ? `sum_r3_good` :
                             (ds.idledKiln ? `sum_r3_idle` :
                             (d.investor === `esg` ? `sum_r3_polarized` :
                             (ds.dividendSilent ? `sum_r3_dividend` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Announce & defend under earnings pressure (Common Error 4).
                switch (d.target) {
                    case `committed`: credDelta += 1.4; coalitionDelta += 4; shareDelta += 5; riskDelta -= 8; coachKey = `coach_r4_committed`; break;
                    case `overpromise`: ds.overPromised = true; credDelta -= 1.6; shareDelta += 3; riskDelta += 9; coachKey = `coach_r4_overpromise`; break;
                    case `vague`: credDelta -= 1.0; coalitionDelta -= 3; riskDelta += 6; coachKey = `coach_r4_vague`; break;
                }

                switch (d.metrics) {
                    case `transparent`: credDelta += 1.0; coalitionDelta += 3; riskDelta -= 5; break;
                    case `hide`: credDelta -= 0.7; riskDelta += 4; coachKey = `coach_r4_hide`; break;
                    case `optics`: credDelta -= 1.0; riskDelta += 6; coachKey = `coach_r4_optics`; break;
                }

                switch (d.proxy) {
                    case `coalition`: coalitionDelta += 6; shareDelta += 6; riskDelta -= 12; if (d.target === `committed`) coachKey = `coach_r4_defend`; break;
                    case `capitulate`: ds.polarizedRun = true; shareDelta -= 6; credDelta -= 0.6; riskDelta += 6; coachKey = `coach_r4_capitulate`; break;
                    case `dismiss`: coalitionDelta -= 5; shareDelta -= 5; riskDelta += 9; coachKey = `coach_r4_proxydismiss`; break;
                }

                if (d.conviction >= 60) { credDelta += 0.5; riskDelta -= 4; }
                else if (d.conviction <= 25) { credDelta -= 0.4; riskDelta += 4; }

                summaryKey = (d.target === `committed` && d.metrics === `transparent` && d.proxy === `coalition`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.abate = Math.max(0, Math.min(100, Math.round((ds.abate + abateDelta) * 10) / 10));
            ds.coalition = Math.max(0, Math.min(100, Math.round(ds.coalition + coalitionDelta)));
            ds.cred = Math.max(0, Math.min(10, Math.round((ds.cred + credDelta) * 10) / 10));
            ds.proxyRisk = Math.max(0, Math.min(100, Math.round(ds.proxyRisk + riskDelta)));

            // ---- Share price is partly DERIVED: the market re-rates on credibility,
            // coalition stability and the carbon liability being managed, plus the direct reaction. ----
            const marketSentiment = (ds.cred - 5) * 1.4 + (ds.coalition - 50) * 0.10 - (ds.proxyRisk - 50) * 0.08;
            ds.share = Math.max(40, Math.round((ds.share + shareDelta + marketSentiment) * 10) / 10);

            // Over-promising strands the plan: a missed interim milestone later cuts credibility & share.
            if (ds.overPromised && round === 4) {
                ds.cred = Math.max(0, ds.cred - 1.0);
                ds.share = Math.max(40, ds.share - 5);
            }
            // Idling the kiln: the work stoppage caps coalition support no matter the emissions win.
            if (ds.idledKiln) {
                ds.coalition = Math.min(ds.coalition, 42);
            }

            ds.abateHistory.push(ds.abate);
            ds.coalitionHistory.push(ds.coalition);
            ds.shareHistory.push(Math.round(ds.share));
            ds.credHistory.push(ds.cred);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                abate: ds.abate,
                abateDelta: Math.round(abateDelta * 10) / 10,
                coalition: ds.coalition,
                coalitionDelta: Math.round(coalitionDelta),
                share: Math.round(ds.share),
                cred: ds.cred,
                credDelta: Math.round(credDelta * 10) / 10,
                proxyRisk: ds.proxyRisk,
                idledKiln: ds.idledKiln,
                overPromised: ds.overPromised,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _riskLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`risk_high`);
            if (v >= 35) return t(`risk_mid`);
            return t(`risk_low`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`abateDisplay`, `domainState.abate`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`coalitionDisplay`, `domainState.coalition`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.boreal-card-coalition`);
                if (card) card.classList.toggle(`boreal-coalition-low`, n < 40);
                return `${n}`;
            });

            uiManager.bind(`shareDisplay`, `domainState.share`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.boreal-card-share`);
                if (card) {
                    card.classList.toggle(`boreal-share-up`, n >= 103);
                    card.classList.toggle(`boreal-share-down`, n < 95);
                }
                return `${n}`;
            });

            uiManager.bind(`credDisplay`, `domainState.cred`, (v) => self._fmtScore(Number(v)));

            uiManager.bind(`threatDisplay`, `domainState.proxyRisk`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.boreal-threat-bar`);
                if (bar) {
                    bar.classList.toggle(`boreal-threat-low`, n < 35);
                    bar.classList.toggle(`boreal-threat-mid`, n >= 35 && n < 60);
                }
                return self._riskLabel(n);
            });

            // Consultation slider readout.
            const li = document.getElementById(`listenInput`);
            const liReadout = document.getElementById(`listenReadout`);
            if (li && liReadout) {
                liReadout.textContent = li.value;
                li.addEventListener(`input`, function() { liReadout.textContent = li.value; });
            }

            // Pace slider readout.
            const pa = document.getElementById(`paceInput`);
            const paReadout = document.getElementById(`paceReadout`);
            if (pa && paReadout) {
                paReadout.textContent = pa.value;
                pa.addEventListener(`input`, function() { paReadout.textContent = pa.value; });
            }

            // Live allocation total for the four-lever budget.
            const allocIds = [`fuelsInput`, `clinkerInput`, `electricInput`, `captureInput`];
            const allocTotalEl = document.getElementById(`allocTotal`);
            const recomputeAlloc = function() {
                let sum = 0;
                allocIds.forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el) { const v = parseFloat(el.value); if (Number.isFinite(v)) sum += v; }
                });
                if (allocTotalEl) {
                    allocTotalEl.textContent = Math.round(sum);
                    const wrap = allocTotalEl.closest(`.boreal-alloc-total`);
                    if (wrap) wrap.classList.toggle(`boreal-alloc-over`, sum > self.BUDGET);
                }
            };
            allocIds.forEach(function(id) {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeAlloc);
            });
            recomputeAlloc();
        }

        _fmtScore(v) {
            // Locale-aware one-decimal score: en "5.0", es "5,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = v.toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            return {
                borealChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Abatement on a credible path (%)`,
                                data: [],
                                borderColor: `#11705a`,
                                backgroundColor: `rgba(17,112,90,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#11705a`,
                                yAxisID: `y`
                            },
                            {
                                label: `Coalition support (0–100)`,
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Share price (indexed, 100 = day 1)`,
                                data: [],
                                borderColor: `#b3541e`,
                                backgroundColor: `rgba(179,84,30,0.10)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
