                                beginAtZero: true, suggestedMax: 120, position: `left`,
                                ticks: { color: `#76858d` }, grid: { color: `rgba(28,37,48,0.06)` },
                                title: { display: true, text: `Index / %`, color: `#76858d` }
                            },
                            x: {
                                ticks: { color: `#76858d` }, grid: { color: `rgba(28,37,48,0.04)` },
                                title: { display: true, text: `Round`, color: `#76858d` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.abateHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                borealChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.abateHistory.map((v) => Math.round(v)) },
                        { data: ds.coalitionHistory },
                        { data: ds.shareHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim replica of the getPerformanceSummary composite (weights unchanged).
            const abate = Math.round(ds.abate);
            const coalition = Math.round(ds.coalition);
            const share = Math.round(ds.share);
            const cred = Math.round(ds.cred * 10) / 10;
            const shareScore = Math.max(0, Math.min(100, (share - 70) * (100 / 50)));
            const credScore = cred * 10;
            return Math.round(abate * 0.26 + coalition * 0.28 + shareScore * 0.22 + credScore * 0.24);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-transition debrief scorecard (was: framework default that
            // discarded score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="lt-cm-target ' + (ok ? 'lt-cm-met' : 'lt-cm-missed') + '">'
                    + '<span class="lt-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.abated, t('tgt_abate'))
                + chip(!!summary.heldCoalition, t('tgt_coalition'))
                + chip(!!summary.defendedShare, t('tgt_share'))
                + chip(!!summary.credible, t('tgt_cred'))
                + chip(!!summary.cleanCommitment, t('tgt_clean'));
            const metric = function (label, val) {
                return '<div class="lt-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_abate'), nz(summary.abate) + '%')
                + metric(t('kpi_coalition'), nz(summary.coalition))
                + metric(t('kpi_share'), nz(summary.share))
                + metric(t('kpi_cred'), nz(summary.cred) + '/10');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="lt-cm">'
                +   '<div class="lt-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="lt-cm-verdict">' + verdict + '</div>'
                +   '<div class="lt-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="lt-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="lt-cm-targets">' + targets + '</div>'
                +   '<div class="lt-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="lt-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const abate = Math.round(ds.abate);
            const coalition = Math.round(ds.coalition);
            const share = Math.round(ds.share);
            const cred = Math.round(ds.cred * 10) / 10;

            // Composite: abatement, coalition, share defence, credibility — balanced.
            const shareScore = Math.max(0, Math.min(100, (share - 70) * (100 / 50))); // 70→0, 120→100
            const credScore = cred * 10;
            const composite = Math.round(
                abate * 0.26 + coalition * 0.28 + shareScore * 0.22 + credScore * 0.24
            );

            const abated = abate >= 35;
            const heldCoalition = coalition >= 60;
            const defendedShare = share >= 98;
            const credible = cred >= 7;
            // The two headline announcement/communication anti-patterns (Common Errors #4 & #5):
            // over-promising public targets under uncertainty, or leaving the dividend question
            // unanswered. Either one disqualifies a genuine, top-verdict transition — the concept
            // is explicit that these set up a credibility/greenwashing crisis or let the market
            // price in the worst, so they must NOT earn "Transition Led".
            const cleanCommitment = !ds.overPromised && !ds.dividendSilent;

            let pattern = `mixed`;
            if (ds.polarizedRun && coalition < 55) pattern = `polarized`;
            else if (ds.idledKiln && coalition <= 45) pattern = `unjust`;
            else if (ds.symbolicBudget && cred < 7) pattern = `symbolic`;
            else if (abated && heldCoalition && credible && defendedShare && cleanCommitment) pattern = `transition`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_destroyed`;
            if (abated && heldCoalition && credible && defendedShare && cleanCommitment && composite >= 75) perfKey = `grade_led`;
            else if (heldCoalition && credible && pattern !== `polarized` && pattern !== `unjust`) perfKey = `grade_coalition`;
            else if (pattern === `polarized`) perfKey = `grade_polarized`;
            else if (pattern === `unjust`) perfKey = `grade_unjust`;
            else if (composite >= 55) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `transition`) insights.push(window.mySimulation.t(`insight_transition`));
            else if (pattern === `polarized`) insights.push(window.mySimulation.t(`insight_polarized`));
            else if (pattern === `unjust`) insights.push(window.mySimulation.t(`insight_unjust`));
            else if (pattern === `symbolic`) insights.push(window.mySimulation.t(`insight_symbolic`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (ds.dividendSilent) insights.push(window.mySimulation.t(`insight_dividend`));
            if (!credible) insights.push(window.mySimulation.t(`insight_cred_low`));
            if (abate < 25) insights.push(window.mySimulation.t(`insight_abate_low`));
            if (share < 92) insights.push(window.mySimulation.t(`insight_share_low`));

            return {
                gradeKey: perfKey,
                score: composite,
                cleanCommitment: cleanCommitment,
                abate: abate,
                coalition: coalition,
                share: share,
                cred: cred,
                abated: abated,
                heldCoalition: heldCoalition,
                defendedShare: defendedShare,
                credible: credible,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.idledKiln && ds.coalition <= 42) return window.mySimulation.t(`hint_idle`);
            if (ds.proxyRisk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.polarizedRun && ds.coalition < 50) return window.mySimulation.t(`hint_polarized`);
            if (ds.symbolicBudget && ds.cred < 6) return window.mySimulation.t(`hint_symbolic`);
            if (ds.share < 92 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_share`);
            if (ds.abate >= 35 && ds.coalition >= 60 && ds.cred >= 7) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.abate`, label: `Abate`, i18nKey: `col_abate`, formatter: (v) => `${Math.round(v)}%` },
